('values:lms_lesson:405','O:31:\"Drupal\\lms_lesson\\Entity\\Lesson\":30:{s:15:\"\0*\0entityTypeId\";s:10:\"lms_lesson\";s:15:\"\0*\0enforceIsNew\";N;s:12:\"\0*\0typedData\";N;s:17:\"\0*\0originalEntity\";N;s:16:\"\0*\0cacheContexts\";a:0:{}s:12:\"\0*\0cacheTags\";a:0:{}s:14:\"\0*\0cacheMaxAge\";i:-1;s:14:\"\0*\0_serviceIds\";a:0:{}s:18:\"\0*\0_entityStorages\";a:0:{}s:9:\"\0*\0values\";a:23:{s:2:\"id\";a:1:{s:9:\"x-default\";s:3:\"405\";}s:4:\"uuid\";a:1:{s:9:\"x-default\";s:36:\"8a6c4744-827b-405d-8ede-f450bfa2b709\";}s:8:\"langcode\";a:1:{s:9:\"x-default\";s:2:\"en\";}s:4:\"name\";a:1:{s:9:\"x-default\";s:59:\"Robotic Process Automation (RPA) for Operational Efficiency\";}s:13:\"field_content\";a:1:{s:9:\"x-default\";a:2:{s:5:\"value\";s:1195:\"<h2>Introduction to RPA</h2><p>Robotic Process Automation (RPA) is a technology that uses software robots to automate repetitive and mundane tasks within business operations. It\'s transforming the way businesses function by increasing efficiency and reducing human error.</p><h2>Benefits of RPA</h2><ul><li>Increased Productivity: RPA can handle high-volume tasks faster than humans.</li><li>Cost Efficiency: Reducing the need for manual labor saves costs.</li><li>Improved Accuracy: Minimizing human errors in data entry and processing.</li></ul><h2>Implementing RPA</h2><p>To implement RPA, businesses must first identify processes that are suitable for automation. This includes tasks that are rule-based, repetitive, and involve digital data.</p><h2>Challenges and Considerations</h2><p>While RPA offers numerous benefits, organizations must consider potential challenges such as change management and the need for ongoing maintenance and support.</p><h2>Future of RPA</h2><p>RPA is expected to evolve with AI integration, making processes even smarter and more efficient. As businesses continue to embrace digital transformation, RPA will play a critical role in operational efficiency.</p>\";s:6:\"format\";s:9:\"full_html\";}}s:10:\"field_type\";a:1:{s:9:\"x-default\";s:4:\"text\";}s:15:\"field_video_url\";a:1:{s:9:\"x-default\";s:119:\"https://www.youtube.com/results?search_query=Robotic+Process+Automation%2C+RPA+for+Business%2C+RPA+Implementation+Guide\";}s:16:\"field_video_file\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:21:\"field_zoom_meeting_id\";a:1:{s:9:\"x-default\";N;}s:19:\"field_zoom_schedule\";a:1:{s:9:\"x-default\";N;}s:19:\"field_scorm_package\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:14:\"field_duration\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:18:\"field_free_preview\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:15:\"field_drip_days\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:6:\"weight\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:6:\"status\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:7:\"created\";a:1:{s:9:\"x-default\";s:10:\"1774442931\";}s:7:\"changed\";a:1:{s:9:\"x-default\";s:10:\"1774519648\";}s:16:\"default_langcode\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:10:\"field_quiz\";a:1:{s:9:\"x-default\";N;}s:21:\"field_pptx_attachment\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:14:\"field_comments\";a:1:{s:9:\"x-default\";a:1:{i:0;a:6:{s:6:\"status\";s:1:\"2\";s:3:\"cid\";s:1:\"0\";s:22:\"last_comment_timestamp\";s:10:\"1774442931\";s:17:\"last_comment_name\";N;s:16:\"last_comment_uid\";s:1:\"0\";s:13:\"comment_count\";s:1:\"0\";}}}s:15:\"field_h5p_embed\";a:1:{s:9:\"x-default\";N;}}s:9:\"\0*\0fields\";a:0:{}s:19:\"\0*\0fieldDefinitions\";N;s:12:\"\0*\0languages\";N;s:14:\"\0*\0langcodeKey\";s:8:\"langcode\";s:21:\"\0*\0defaultLangcodeKey\";s:16:\"default_langcode\";s:17:\"\0*\0activeLangcode\";s:9:\"x-default\";s:28:\"\0*\0enforceDefaultTranslation\";N;s:18:\"\0*\0defaultLangcode\";s:2:\"en\";s:15:\"\0*\0translations\";a:1:{s:9:\"x-default\";a:1:{s:6:\"status\";i:1;}}s:24:\"\0*\0translationInitialize\";b:0;s:14:\"\0*\0newRevision\";b:0;s:20:\"\0*\0isDefaultRevision\";b:1;s:13:\"\0*\0entityKeys\";a:4:{s:6:\"bundle\";s:10:\"lms_lesson\";s:2:\"id\";s:3:\"405\";s:4:\"uuid\";s:36:\"8a6c4744-827b-405d-8ede-f450bfa2b709\";s:9:\"published\";s:1:\"1\";}s:25:\"\0*\0translatableEntityKeys\";a:3:{s:5:\"label\";a:1:{s:9:\"x-default\";s:59:\"Robotic Process Automation (RPA) for Operational Efficiency\";}s:8:\"langcode\";a:1:{s:9:\"x-default\";s:2:\"en\";}s:16:\"default_langcode\";a:1:{s:9:\"x-default\";s:1:\"1\";}}s:12:\"\0*\0validated\";b:0;s:21:\"\0*\0validationRequired\";b:0;s:19:\"\0*\0loadedRevisionId\";N;s:33:\"\0*\0revisionTranslationAffectedKey\";s:29:\"revision_translation_affected\";s:37:\"\0*\0enforceRevisionTranslationAffected\";a:0:{}s:12:\"\0*\0isSyncing\";b:0;}',-1,1774587023.018,1,'entity_field_info','0'),
('values:lms_lesson:406','O:31:\"Drupal\\lms_lesson\\Entity\\Lesson\":30:{s:15:\"\0*\0entityTypeId\";s:10:\"lms_lesson\";s:15:\"\0*\0enforceIsNew\";N;s:12:\"\0*\0typedData\";N;s:17:\"\0*\0originalEntity\";N;s:16:\"\0*\0cacheContexts\";a:0:{}s:12:\"\0*\0cacheTags\";a:0:{}s:14:\"\0*\0cacheMaxAge\";i:-1;s:14:\"\0*\0_serviceIds\";a:0:{}s:18:\"\0*\0_entityStorages\";a:0:{}s:9:\"\0*\0values\";a:23:{s:2:\"id\";a:1:{s:9:\"x-default\";s:3:\"406\";}s:4:\"uuid\";a:1:{s:9:\"x-default\";s:36:\"d7c86d69-c20e-4a72-a8f2-10c7a7b5ce44\";}s:8:\"langcode\";a:1:{s:9:\"x-default\";s:2:\"en\";}s:4:\"name\";a:1:{s:9:\"x-default\";s:56:\"AI in Human Resources: Recruitment and Talent Management\";}s:13:\"field_content\";a:1:{s:9:\"x-default\";a:2:{s:5:\"value\";s:1376:\"<h1>AI in Human Resources: Recruitment and Talent Management</h1><p>Artificial Intelligence is revolutionizing the way organizations manage their human resources, particularly in recruitment and talent management. By leveraging AI, HR departments can streamline processes and make more informed decisions.</p><h2>Automating Recruitment Processes</h2><p>AI-powered tools can automate repetitive tasks such as resume screening and initial candidate assessments. This allows HR professionals to focus on more strategic activities.</p><h2>Enhancing Talent Acquisition</h2><p>AI can analyze large datasets to identify potential candidates with the right skills and cultural fit for the organization, significantly improving the talent acquisition process.</p><h2>Personalizing Employee Experiences</h2><p>With AI, companies can create personalized career development plans for employees, enhancing engagement and retention.</p><h2>Predictive Analytics for Workforce Planning</h2><p>AI-driven predictive analytics can help HR teams anticipate future workforce needs and plan accordingly, ensuring the organization is always prepared for changes in demand.</p><ul><li>Resume Screening Automation</li><li>Predictive Workforce Analytics</li><li>Personalized Employee Development</li></ul><p>These advancements are transforming HR into a more strategic partner within organizations.</p>\";s:6:\"format\";s:9:\"full_html\";}}s:10:\"field_type\";a:1:{s:9:\"x-default\";s:4:\"text\";}s:15:\"field_video_url\";a:1:{s:9:\"x-default\";s:137:\"https://www.youtube.com/results?search_query=AI+in+HR+recruitment+talent+management%2C+AI+recruitment+automation%2C+AI+talent+acquisition\";}s:16:\"field_video_file\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:21:\"field_zoom_meeting_id\";a:1:{s:9:\"x-default\";N;}s:19:\"field_zoom_schedule\";a:1:{s:9:\"x-default\";N;}s:19:\"field_scorm_package\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:14:\"field_duration\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:18:\"field_free_preview\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:15:\"field_drip_days\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:6:\"weight\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:6:\"status\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:7:\"created\";a:1:{s:9:\"x-default\";s:10:\"1774442931\";}s:7:\"changed\";a:1:{s:9:\"x-default\";s:10:\"1774519648\";}s:16:\"default_langcode\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:10:\"field_quiz\";a:1:{s:9:\"x-default\";N;}s:21:\"field_pptx_attachment\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:14:\"field_comments\";a:1:{s:9:\"x-default\";a:1:{i:0;a:6:{s:6:\"status\";s:1:\"2\";s:3:\"cid\";s:1:\"0\";s:22:\"last_comment_timestamp\";s:10:\"1774442931\";s:17:\"last_comment_name\";N;s:16:\"last_comment_uid\";s:1:\"0\";s:13:\"comment_count\";s:1:\"0\";}}}s:15:\"field_h5p_embed\";a:1:{s:9:\"x-default\";N;}}s:9:\"\0*\0fields\";a:0:{}s:19:\"\0*\0fieldDefinitions\";N;s:12:\"\0*\0languages\";N;s:14:\"\0*\0langcodeKey\";s:8:\"langcode\";s:21:\"\0*\0defaultLangcodeKey\";s:16:\"default_langcode\";s:17:\"\0*\0activeLangcode\";s:9:\"x-default\";s:28:\"\0*\0enforceDefaultTranslation\";N;s:18:\"\0*\0de