('values:lms_lesson:532','O:31:\"Drupal\\lms_lesson\\Entity\\Lesson\":30:{s:15:\"\0*\0entityTypeId\";s:10:\"lms_lesson\";s:15:\"\0*\0enforceIsNew\";N;s:12:\"\0*\0typedData\";N;s:17:\"\0*\0originalEntity\";N;s:16:\"\0*\0cacheContexts\";a:0:{}s:12:\"\0*\0cacheTags\";a:0:{}s:14:\"\0*\0cacheMaxAge\";i:-1;s:14:\"\0*\0_serviceIds\";a:0:{}s:18:\"\0*\0_entityStorages\";a:0:{}s:9:\"\0*\0values\";a:23:{s:2:\"id\";a:1:{s:9:\"x-default\";s:3:\"532\";}s:4:\"uuid\";a:1:{s:9:\"x-default\";s:36:\"ed9774b0-b90d-4039-95b1-b9b6f97ed650\";}s:8:\"langcode\";a:1:{s:9:\"x-default\";s:2:\"en\";}s:4:\"name\";a:1:{s:9:\"x-default\";s:43:\"What is Generative AI and How Does it Work?\";}s:13:\"field_content\";a:1:{s:9:\"x-default\";a:2:{s:5:\"value\";s:1236:\"<h1>Understanding Generative AI</h1><p>Generative AI refers to a class of artificial intelligence that is designed to generate content, such as text, images, or music, that is indistinguishable from content created by humans. It leverages deep learning techniques and neural networks to produce these outputs.</p><h2>How Generative AI Works</h2><p>At its core, generative AI models are trained on large datasets to understand patterns and features in the data. These models, once trained, can create new content by predicting what comes next in a sequence, whether it\'s words in a sentence or pixels in an image.</p><h3>Key Components</h3><ul><li><strong>Neural Networks:</strong> These are the backbone of generative AI, enabling the processing of complex data patterns.</li><li><strong>Training Data:</strong> The quality and diversity of data used for training significantly impact the model\'s performance.</li><li><strong>Generative Adversarial Networks (GANs):</strong> A common architecture used in generative AI, where two neural networks contest with each other to improve the quality of generated data.</li></ul><p>Generative AI is transforming industries by automating creative processes and offering new ways to innovate.</p>\";s:6:\"format\";s:9:\"full_html\";}}s:10:\"field_type\";a:1:{s:9:\"x-default\";s:4:\"text\";}s:15:\"field_video_url\";a:1:{s:9:\"x-default\";s:130:\"https://www.youtube.com/results?search_query=Generative+AI+explanation%2C+how+generative+AI+works%2C+introduction+to+generative+AI\";}s:16:\"field_video_file\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:21:\"field_zoom_meeting_id\";a:1:{s:9:\"x-default\";N;}s:19:\"field_zoom_schedule\";a:1:{s:9:\"x-default\";N;}s:19:\"field_scorm_package\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:14:\"field_duration\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:18:\"field_free_preview\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:15:\"field_drip_days\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:6:\"weight\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:6:\"status\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:7:\"created\";a:1:{s:9:\"x-default\";s:10:\"1774442931\";}s:7:\"changed\";a:1:{s:9:\"x-default\";s:10:\"1774519648\";}s:16:\"default_langcode\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:10:\"field_quiz\";a:1:{s:9:\"x-default\";N;}s:21:\"field_pptx_attachment\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:14:\"field_comments\";a:1:{s:9:\"x-default\";a:1:{i:0;a:6:{s:6:\"status\";s:1:\"2\";s:3:\"cid\";s:1:\"0\";s:22:\"last_comment_timestamp\";s:10:\"1774442931\";s:17:\"last_comment_name\";N;s:16:\"last_comment_uid\";s:1:\"0\";s:13:\"comment_count\";s:1:\"0\";}}}s:15:\"field_h5p_embed\";a:1:{s:9:\"x-default\";N;}}s:9:\"\0*\0fields\";a:0:{}s:19:\"\0*\0fieldDefinitions\";N;s:12:\"\0*\0languages\";N;s:14:\"\0*\0langcodeKey\";s:8:\"langcode\";s:21:\"\0*\0defaultLangcodeKey\";s:16:\"default_langcode\";s:17:\"\0*\0activeLangcode\";s:9:\"x-default\";s:28:\"\0*\0enforceDefaultTranslation\";N;s:18:\"\0*\0defaultLangcode\";s:2:\"en\";s:15:\"\0*\0translations\";a:1:{s:9:\"x-default\";a:1:{s:6:\"status\";i:1;}}s:24:\"\0*\0translationInitialize\";b:0;s:14:\"\0*\0newRevision\";b:0;s:20:\"\0*\0isDefaultRevision\";b:1;s:13:\"\0*\0entityKeys\";a:4:{s:6:\"bundle\";s:10:\"lms_lesson\";s:2:\"id\";s:3:\"532\";s:4:\"uuid\";s:36:\"ed9774b0-b90d-4039-95b1-b9b6f97ed650\";s:9:\"published\";s:1:\"1\";}s:25:\"\0*\0translatableEntityKeys\";a:3:{s:5:\"label\";a:1:{s:9:\"x-default\";s:43:\"What is Generative AI and How Does it Work?\";}s:8:\"langcode\";a:1:{s:9:\"x-default\";s:2:\"en\";}s:16:\"default_langcode\";a:1:{s:9:\"x-default\";s:1:\"1\";}}s:12:\"\0*\0validated\";b:0;s:21:\"\0*\0validationRequired\";b:0;s:19:\"\0*\0loadedRevisionId\";N;s:33:\"\0*\0revisionTranslationAffectedKey\";s:29:\"revision_translation_affected\";s:37:\"\0*\0enforceRevisionTranslationAffected\";a:0:{}s:12:\"\0*\0isSyncing\";b:0;}',-1,1774587141.821,1,'entity_field_info','0'),
('values:lms_lesson:533','O:31:\"Drupal\\lms_lesson\\Entity\\Lesson\":30:{s:15:\"\0*\0entityTypeId\";s:10:\"lms_lesson\";s:15:\"\0*\0enforceIsNew\";N;s:12:\"\0*\0typedData\";N;s:17:\"\0*\0originalEntity\";N;s:16:\"\0*\0cacheContexts\";a:0:{}s:12:\"\0*\0cacheTags\";a:0:{}s:14:\"\0*\0cacheMaxAge\";i:-1;s:14:\"\0*\0_serviceIds\";a:0:{}s:18:\"\0*\0_entityStorages\";a:0:{}s:9:\"\0*\0values\";a:23:{s:2:\"id\";a:1:{s:9:\"x-default\";s:3:\"533\";}s:4:\"uuid\";a:1:{s:9:\"x-default\";s:36:\"9b01ebea-77a5-4831-8d74-1e9ee05c2785\";}s:8:\"langcode\";a:1:{s:9:\"x-default\";s:2:\"en\";}s:4:\"name\";a:1:{s:9:\"x-default\";s:38:\"Large Language Models (LLMs) Explained\";}s:13:\"field_content\";a:1:{s:9:\"x-default\";a:2:{s:5:\"value\";s:1121:\"<h2>Understanding Large Language Models (LLMs)</h2><p>Large Language Models (LLMs) are a type of artificial intelligence designed to understand and generate human-like text. They are trained on vast amounts of data, enabling them to perform a variety of language tasks.</p><h3>How LLMs Work</h3><p>LLMs use a neural network architecture, often based on transformers, to process and generate text. They predict the next word in a sentence by considering the context of the words that came before.</p><h3>Applications of LLMs</h3><ul><li><strong>Text Generation:</strong> LLMs can create coherent and contextually relevant text, making them useful for content creation.</li><li><strong>Translation:</strong> They can translate text between different languages with high accuracy.</li><li><strong>Summarization:</strong> LLMs can condense large bodies of text into concise summaries.</li></ul><h3>Challenges and Ethical Considerations</h3><p>Despite their capabilities, LLMs face challenges such as bias in training data, which can lead to biased outputs. Ethical use of LLMs involves ensuring transparency and fairness.</p>\";s:6:\"format\";s:9:\"full_html\";}}s:10:\"field_type\";a:1:{s:9:\"x-default\";s:4:\"text\";}s:15:\"field_video_url\";a:1:{s:9:\"x-default\";s:129:\"https://www.youtube.com/results?search_query=Large+Language+Models%2C+AI+text+generation%2C+transformer+models%2C+GPT-3%2C+OpenAI\";}s:16:\"field_video_file\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:21:\"field_zoom_meeting_id\";a:1:{s:9:\"x-default\";N;}s:19:\"field_zoom_schedule\";a:1:{s:9:\"x-default\";N;}s:19:\"field_scorm_package\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:14:\"field_duration\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:18:\"field_free_preview\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:15:\"field_drip_days\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:6:\"weight\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:6:\"status\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:7:\"created\";a:1:{s:9:\"x-default\";s:10:\"1774442931\";}s:7:\"changed\";a:1:{s:9:\"x-default\";s:10:\"1774519648\";}s:16:\"default_langcode\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:10:\"field_quiz\";a:1:{s:9:\"x-default\";N;}s:21:\"field_pptx_attachment\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:14:\"field_comments\";a:1:{s:9:\"x-default\";a:1:{i:0;a:6:{s:6:\"status\";s:1:\"2\";s:3:\"cid\";s:1:\"0\";s:22:\"last_comment_timestamp\";s:10:\"1774442931\";s:17:\"last_comment_name\";N;s:16:\"last_comment_uid\";s:1:\"0\";s:13:\"comment_count\";s:1:\"0\";}}}s:15:\"field_h5p_embed\";a:1:{s:9:\"x-default\";N;}}s:9:\"\0*\0fields\";a:0:{}s:19:\"\0*\0fieldDefinitions\";N;s:12:\"\0*\0languages\";N;s:14:\"\0*\0langcodeKey\";s:8:\"langcode\";s:21:\"\0*\0defaultLangcodeKey\";s:16:\"default_langcode\";s:17:\"\0*\0activeLangcode\";s:9:\"x-default\";s:28:\"\0*\0enforceDefaultTranslation\";N;s:18:\"\0*\0defaultLangcode\";s:2:\"en\";s:15:\"\0*\0translations\";a:1:{s:9:\"x-default\";a:1:{s:6:\"status\";i:1;}}s:24:\"\0*\0translationInitialize\";b:0;s:14:\"\0*\0newRevision\";b:0;s:20:\"\0*\0isDefaultRevision\";b:1;s:13:\"\0*\0entityKeys\";a:4:{s:6:\"bundle\";s:10:\"lms_lesson\";s:2:\"id\";s:3:\"533\";s:4:\"uuid\";s:36:\"9b01ebea-77a5-4831-8d74-1e9ee05c2785\";s:9:\"published\";s:1:\"1\";}s:25:\"\0*\0translatableEntityKeys\";a:3:{s:5:\"label\";a:1:{s:9:\"x-default\";s:38:\"Large Language Models (LLMs) Explained\";}s:8:\"langcode\";a:1:{s:9:\"x-default\";s:2:\"en\";}s:16:\"default_langcode\";a:1:{s:9:\"x-default\";s:1:\"1\";}}s:12:\"\0*\0validated\";b:0;s:21:\"\0*\0validationRequired\";b:0;s:19:\"\0*\0loadedRevisionId\";N;s:33:\"\0*\0revisionTranslationAffectedKey\";s:29:\"revision_translation_affected\";s:37:\"\0*\0enforceRevisionTranslationAffected\";a:0:{}s:12:\"\0*\0isSyncing\";b:0;}',-1,1774587141.821,1,'entity_field_info','0'),
('values:lms_lesson:534','O:31:\"Drupal\\lms_lesson\\Entity\\Lesson\":30:{s:15:\"\0*\0entityTypeId\";s:10:\"lms_lesson\";s:15:\"\0*\0enforceIsNew\";N;s:12:\"\0*\0typedData\";N;s:17:\"\0*\0originalEntity\";N;s:16:\"\0*\0cacheContexts\";a:0:{}s:12:\"\0*\0cacheTags\";a:0:{}s:14:\"\0*\0cacheMaxAge\";i:-1;s:14:\"\0*\0_serviceIds\";a:0:{}s:18:\"\0*\0_entityStorages\";a:0:{}s:9:\"\0*\0values\";a:23:{s:2:\"id\";a:1:{s:9:\"x-default\";s:3:\"534\";}s:4:\"uuid\";a:1:{s:9:\"x-default\";s:36:\"1b6a0f13-d656-459a-802c-feccf2e242d8\";}s:8:\"langcode\";a:1:{s:9:\"x-default\";s:2:\"en\";}s:4:\"name\";a:1:{s:9:\"x-default\";s:43:\"Generative AI for Text and Content Creation\";}s:13:\"field_content\";a:1:{s:9:\"x-default\";a:2:{s:5:\"value\";s:1404:\"<h1>Generative AI for Text and Content Creation</h1><p>Generative AI is revolutionizing the way we create text and content. By leveraging advanced machine learning models, such as Large Language Models (LLMs), it is now possible to generate coherent, contextually relevant, and creative text outputs.</p><h2>Understanding the Basics</h2><p>At its core, generative AI involves training models on vast datasets to enable them to understand and replicate human-like text patterns. This process involves deep learning techniques and neural network architectures.</p><h3>Applications in Text Generation</h3><p>Generative AI can be applied in various domains, including content creation, report generation, and automated customer service responses. It can help streamline workflows by automating repetitive writing tasks.</p><ul><li>Content creation for blogs and articles</li><li>Generating product descriptions</li><li>Creating personalized marketing content</li></ul><h3>Challenges and Considerations</h3><p>While generative AI provides significant benefits, it also poses challenges such as ensuring ethical use, avoiding biases in generated text, and maintaining content quality.</p><h2>Future Prospects</h2><p>The potential of generative AI in content creation is vast. As models continue to evolve, they are expected to assist more in creative writing, journalism, and personalized content delivery.</p>\";s:6:\"format\";s:9:\"full_html\";}}s:10:\"field_type\";a:1:{s:9:\"x-default\";s:4:\"text\";}s:15:\"field_video_url\";a:1:{s:9:\"x-default\";s:89:\"https://www.youtube.com/results?search_query=Generative+AI+text+content+creation+tutorial\";}s:16:\"field_video_file\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:21:\"field_zoom_meeting_id\";a:1:{s:9:\"x-default\";N;}s:19:\"field_zoom_schedule\";a:1:{s:9:\"x-default\";N;}s:19:\"field_scorm_package\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:14:\"field_duration\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:18:\"field_free_preview\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:15:\"field_drip_days\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:6:\"weight\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:6:\"status\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:7:\"created\";a:1:{s:9:\"x-default\";s:10:\"1774442931\";}s:7:\"changed\";a:1:{s:9:\"x-default\";s:10:\"1774519648\";}s:16:\"default_langcode\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:10:\"field_quiz\";a:1:{s:9:\"x-default\";N;}s:21:\"field_pptx_attachment\";a:1:{s:9:\"x-default\";a:3:{s:9:\"target_id\";N;s:7:\"display\";N;s:11:\"description\";N;}}s:14:\"field_comments\";a:1:{s:9:\"x-default\";a:1:{i:0;a:6:{s:6:\"status\";s:1:\"2\";s:3:\"cid\";s:1:\"0\";s:22:\"last_comment_timestamp\";s:10:\"1774442931\";s:17:\"last_comment_name\";N;s:16:\"last_comment_uid\";s:1:\"0\";s:13:\"comment_count\";s:1:\"0\";}}}s:15:\"field_h5p_embed\";a:1:{s:9:\"x-default\";N;}}s:9:\"\0*\0fields\";a:0:{}s:19:\"\0*\0fieldDefinitions\";N;s:12:\"\0*\0languages\";N;s:14:\"\0*\0langcodeKey\";s:8:\"langcode\";s:21:\"\0*\0defaultLangcodeKey\";s:16:\"default_langcode\";s:17:\"\0*\0activeLangcode\";s:9:\"x-default\";s:28:\"\0*\0enforceDefaultTranslation\";N;s:18:\"\0*\0defaultLangcode\";s:2:\"en\";s:15:\"